css:
.tlsdesign-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 26px;
    color: #2b2723;
    background: linear-gradient(170deg, #f7f3ec 0%, #efe7da 100%);
    border-radius: 16px;
}

.tlsdesign-container * {
    box-sizing: border-box;
}

.tlsdesign-header {
    text-align: center;
    padding: 30px 24px 26px;
    background: linear-gradient(135deg, #4a1d2b 0%, #6c2a3c 55%, #8a3b4c 100%);
    color: #fbf3ee;
    border-radius: 14px;
    margin-bottom: 22px;
    border: 1px solid #3a1622;
    box-shadow: 0 14px 36px rgba(74, 29, 43, 0.35);
}

.tlsdesign-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #fff;
    font-family: Georgia, 'Times New Roman', serif;
}

.tlsdesign-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0c987;
    background: rgba(240, 201, 135, 0.14);
    border: 1px solid rgba(240, 201, 135, 0.40);
    padding: 5px 15px;
    border-radius: 999px;
}

.tlsdesign-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #f1ddd6;
}

.tlsdesign-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5d52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.tlsdesign-period-counter #currentDay,
.tlsdesign-period-counter #maxPeriods {
    font-weight: 800;
    color: #8a3b4c;
}

.tlsdesign-round-name {
    background: rgba(138, 59, 76, 0.12);
    color: #8a3b4c;
    padding: 3px 13px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.tlsdesign-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #946417;
    background: rgba(240, 201, 135, 0.30);
    border: 1px solid rgba(148, 100, 23, 0.30);
    padding: 4px 13px;
    border-radius: 999px;
}

.tlsdesign-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.tlsdesign-status-card {
    background: #fffaf3;
    border-radius: 13px;
    padding: 16px 16px 14px;
    border: 1px solid #e3d6c4;
    box-shadow: 0 6px 16px rgba(74, 29, 43, 0.08);
    border-top: 4px solid #8a3b4c;
}

.tlsdesign-card-uplift { border-top-color: #2e7d68; }
.tlsdesign-card-transfer { border-top-color: #356a9e; }
.tlsdesign-card-sponsor { border-top-color: #8a3b4c; }
.tlsdesign-card-budget { border-top-color: #b07a18; }

.tlsdesign-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a6a;
}

.tlsdesign-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2723;
    font-variant-numeric: tabular-nums;
}

.tlsdesign-card-uplift .tlsdesign-value { color: #2e7d68; }
.tlsdesign-card-transfer .tlsdesign-value { color: #356a9e; }
.tlsdesign-card-sponsor .tlsdesign-value { color: #8a3b4c; }
.tlsdesign-card-budget .tlsdesign-value { color: #b07a18; }

.tlsdesign-sublabel {
    font-size: 0.75rem;
    color: #9a8a78;
    line-height: 1.35;
}

.tlsdesign-sponsor-high { border-top-color: #2e7d68; }
.tlsdesign-sponsor-high .tlsdesign-value { color: #2e7d68; }
.tlsdesign-sponsor-low { border-top-color: #b23b3b; }
.tlsdesign-sponsor-low .tlsdesign-value { color: #b23b3b; }

.tlsdesign-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffaf3;
    border: 1px solid #e3d6c4;
    color: #4a4038;
    padding: 11px 18px;
    border-radius: 11px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.tlsdesign-budget-bar #budgetDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #b07a18;
}

.tlsdesign-budget-over #budgetDisplay { color: #b23b3b; }

.tlsdesign-briefing {
    display: flex;
    gap: 14px;
    background: #fffaf3;
    border-left: 5px solid #8a3b4c;
    border-radius: 11px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 29, 43, 0.08);
}

.tlsdesign-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.tlsdesign-briefing-title {
    font-weight: 800;
    font-size: 1.12rem;
    color: #6c2a3c;
    margin-bottom: 6px;
    font-family: Georgia, 'Times New Roman', serif;
}

.tlsdesign-briefing-text {
    font-size: 0.96rem;
    line-height: 1.6;
    color: #4a4038;
}

.tlsdesign-briefing-text strong { color: #8a3b4c; }
.tlsdesign-briefing-text em { color: #946417; font-style: italic; }

.tlsdesign-controls {
    background: #fffaf3;
    border-radius: 13px;
    padding: 22px 24px;
    margin-bottom: 18px;
    border: 1px solid #e3d6c4;
    box-shadow: 0 6px 16px rgba(74, 29, 43, 0.08);
}

.tlsdesign-controls h3 {
    margin: 0 0 16px;
    font-size: 1.14rem;
    font-weight: 800;
    color: #6c2a3c;
    border-bottom: 2px solid #ecdfcd;
    padding-bottom: 8px;
    font-family: Georgia, 'Times New Roman', serif;
}

.tlsdesign-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.93rem;
    color: #4a4038;
    margin: 16px 0 6px;
}

.tlsdesign-container select,
.tlsdesign-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c8b2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf9;
    color: #2b2723;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.tlsdesign-container select:focus,
.tlsdesign-container input[type="number"]:focus {
    outline: none;
    border-color: #8a3b4c;
    box-shadow: 0 0 0 3px rgba(138, 59, 76, 0.16);
}

.tlsdesign-container select option {
    background-color: #fffdf9;
    color: #2b2723;
}

.tlsdesign-range-readout,
.tlsdesign-alloc-readout {
    font-size: 0.89rem;
    font-weight: 700;
    color: #6b5d52;
    margin-top: 6px;
}

.tlsdesign-range-readout span:last-child,
.tlsdesign-alloc-readout span:nth-child(2) {
    color: #8a3b4c;
    font-weight: 800;
}

.tlsdesign-hint {
    font-size: 0.81rem;
    color: #9a8a78;
    margin-top: 5px;
    line-height: 1.45;
}

.tlsdesign-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.tlsdesign-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6efe3;
    border: 1px solid #e3d6c4;
    border-radius: 9px;
    padding: 9px 13px;
}

.tlsdesign-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a4038;
}

.tlsdesign-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.tlsdesign-container .btn {
    margin-top: 20px;
    font-weight: 700;
}

.tlsdesign-container .btn-primary {
    background: linear-gradient(135deg, #6c2a3c 0%, #8a3b4c 100%);
    border: none;
    color: #fff4ee;
    padding: 12px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(108, 42, 60, 0.32);
}

.tlsdesign-container .btn-primary:hover {
    filter: brightness(1.08);
}

.tlsdesign-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c8b2;
    color: #8a7a6a;
    background: transparent;
}

.tlsdesign-coach {
    background: linear-gradient(160deg, #fbf3ee 0%, #f3e6dd 100%);
    color: #4a3a32;
    border: 1px solid #e2cdc2;
    border-radius: 13px;
    padding: 18px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 29, 43, 0.08);
}

.tlsdesign-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8a3b4c;
    margin-bottom: 8px;
}

.tlsdesign-coach-body {
    font-size: 0.96rem;
    line-height: 1.6;
    font-style: italic;
}

.tlsdesign-coach-body strong { color: #8a3b4c; font-style: normal; }
.tlsdesign-coach-body em { color: #946417; }

.tlsdesign-history,
.tlsdesign-chart {
    background: #fffaf3;
    border-radius: 13px;
    padding: 18px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3d6c4;
    box-shadow: 0 6px 16px rgba(74, 29, 43, 0.08);
}

.tlsdesign-history h3,
.tlsdesign-chart h3 {
    margin: 0 0 14px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #6c2a3c;
    font-family: Georgia, 'Times New Roman', serif;
}

.tlsdesign-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4038;
}

.tlsdesign-container table#usfHistoryTable th {
    background: #f3e6dd;
    color: #6c2a3c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2cdc2;
}

.tlsdesign-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecdfcd;
    color: #4a4038;
}

.tlsdesign-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf3ea;
}

.tlsdesign-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .tlsdesign-container {
        padding: 14px;
    }
    .tlsdesign-header h1 {
        font-size: 1.75rem;
    }
    .tlsdesign-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .tlsdesign-value {
        font-size: 2.05rem;
    }
    .tlsdesign-clock {
        margin-left: 0;
    }
    .tlsdesign-period-counter {
        font-size: 0.88rem;
    }
    .tlsdesign-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .tlsdesign-alloc-row {
        flex-wrap: wrap;
    }
    .tlsdesign-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .tlsdesign-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .thm-cm-*, Thames teal/navy/gold) ── */
.thm-cm { margin-top: 8px; }
.thm-cm-incomplete { text-align: center; color: #4f5b60; font-size: 1rem; padding: 18px; }
.thm-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.thm-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #12363f 0%, #1c6b73 55%, #cfa53f 140%); color: #fff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(18,54,63,0.28); }
.thm-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.thm-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.thm-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #efdca7; }
.thm-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fff; border: 1px solid #d7e2e2; border-left: 5px solid #1c6b73; border-radius: 14px; padding: 16px 20px; }
.thm-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #566266; }
.thm-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #12363f; line-height: 1.15; }
.thm-cm-section { margin-bottom: 16px; }
.thm-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #566266; margin-bottom: 8px; }
.thm-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.thm-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.thm-cm-ok { background: #e5f2f0; color: #145b52; border-color: #aed9cf; }
.thm-cm-no { background: #fbecea; color: #a5382a; border-color: #eec4bd; }
.thm-cm-ico { font-weight: 800; }
.thm-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.thm-cm-kpi { background: #f2f7f6; border: 1px solid #dce7e5; border-radius: 12px; padding: 12px 14px; text-align: center; }
.thm-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #12363f; }
.thm-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #566266; }
.thm-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #8a9698; }
.thm-cm-insights { margin: 0; padding-left: 18px; }
.thm-cm-insights li { font-size: 0.9rem; color: #33403f; margin-bottom: 6px; line-height: 1.45; }

