(function() {
    'use strict';

    class ThamesDesignAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Design the Programme`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Thames Leadership Studio / Britannia Severn plc).
            this.BUDGET = 600;          // £600k hard delivery ceiling (in £k)
            this.COHORT = 120;          // 120 senior leaders
            this.COACH_ALL = 250;       // ~£250k to coach all 120 one-to-one
            this.OVER_DESIGN = 840;     // ~£840k = the fully high-transfer "blow-out" design (~40% over)

            // Concept truths — the diagnosis the evidence actually supports.
            this.TRUE_GAP = `collective`;   // merger silos = the sponsor's number-one gap
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    uplift: 15,         // projected capability gap-closure (0–100)
                    transfer: 15,       // behaviour change back at work (0–100)
                    sponsor: 20,        // board confidence the design works at 9 months (0–100)
                    discipline: 50,     // budget discipline (0–100), penalised by overspend/slack/untargeted
                    budgetUsed: 0,      // £k of delivery budget committed (set in R3)
                    primaryGap: ``,     // the named priority gap (R1)
                    diagnosed: false,   // did R1 trace symptoms to gaps?
                    lopsided: false,    // did R2 over-weight one element?
                    overBudget: false,  // did R3 breach £600k?
                    happySheet: false,  // did R4 optimise for satisfaction?
                    upliftHistory: [15],
                    transferHistory: [15],
                    sponsorHistory: [20],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    primaryGap: `everything`,
                    symptom: `menu`,
                    descope: `none`,
                    wSelf: 34,
                    wColl: 33,
                    wComp: 33,
                    sequence: `random`,
                    faculty: 150,
                    action: 150,
                    coaching: 150,
                    labs: 100,
                    peer: 50,
                    scale: `everyone`,
                    pitch: `inspire`,
                    measure: `happysheet`,
                    pressure: `fold`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pg = document.getElementById(`primaryGapInput`);
                const sy = document.getElementById(`symptomInput`);
                const de = document.getElementById(`descopeInput`);
                if (pg) decisions.primaryGap = pg.value;
                if (sy) decisions.symptom = sy.value;
                if (de) decisions.descope = de.value;
            } else if (round === 2) {
                const ws = document.getElementById(`wSelfInput`);
                const wc = document.getElementById(`wCollInput`);
                const wp = document.getElementById(`wCompInput`);
                const sq = document.getElementById(`sequenceInput`);
                if (ws) decisions.wSelf = parseInt(ws.value, 10);
                if (wc) decisions.wColl = parseInt(wc.value, 10);
                if (wp) decisions.wComp = parseInt(wp.value, 10);
                if (sq) decisions.sequence = sq.value;
                const parts = [decisions.wSelf, decisions.wColl, decisions.wComp];
                if (parts.some((v) => !Number.isFinite(v) || v < 0 || v > 100)) {
                    warn(`warn_weight_range`); return false;
                }
                if (decisions.wSelf + decisions.wColl + decisions.wComp !== 100) {
                    warn(`warn_weight_total`); return false;
                }
            } else if (round === 3) {
                const fa = document.getElementById(`facultyInput`);
                const ac = document.getElementById(`actionInput`);
                const co = document.getElementById(`coachingInput`);
                const la = document.getElementById(`labsInput`);
                const pe = document.getElementById(`peerInput`);
                const sc = document.getElementById(`scaleInput`);
                if (fa) decisions.faculty = parseFloat(fa.value);
                if (ac) decisions.action = parseFloat(ac.value);
                if (co) decisions.coaching = parseFloat(co.value);
                if (la) decisions.labs = parseFloat(la.value);
                if (pe) decisions.peer = parseFloat(pe.value);
                if (sc) decisions.scale = sc.value;
                const lines = [decisions.faculty, decisions.action, decisions.coaching, decisions.labs, decisions.peer];
                if (lines.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_cost_negative`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const me = document.getElementById(`measureInput`);
                const pr = document.getElementById(`pressureInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (me) decisions.measure = me.value;
                if (pr) decisions.pressure = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite, extracted so calculateResults and getPerformanceSummary agree.
            const uplift = Math.round(ds.uplift);
            const transfer = Math.round(ds.transfer);
            const sponsor = Math.round(ds.sponsor);
            const discipline = Math.round(ds.discipline);
            return Math.round(
                transfer * 0.34 + uplift * 0.24 + sponsor * 0.28 + discipline * 0.14
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let upliftDelta = 0, transferDelta = 0, sponsorDelta = 0, disciplineDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — diagnosis precedes design (Common Error 1).
                // Trace symptom -> underlying gap before naming any activity.
                switch (d.symptom) {
                    case `evidence`: ds.diagnosed = true; sponsorDelta += 10; upliftDelta += 4; coachKey = `coach_r1_evidence`; break;
                    case `menu`: sponsorDelta -= 8; upliftDelta -= 2; coachKey = `coach_r1_menu`; break;
                    case `sponsor`: sponsorDelta -= 2; coachKey = `coach_r1_sponsor`; break;
                }

                // Name the PRIMARY gap. The merger-silo collective-leadership gap is
                // the sponsor's number-one priority; targeting it lands hardest.
                ds.primaryGap = d.primaryGap;
                switch (d.primaryGap) {
                    case `collective`: sponsorDelta += 8; upliftDelta += 6; if (d.symptom === `evidence`) coachKey = `coach_r1_sharp`; break;
                    case `selfaware`: upliftDelta += 3; sponsorDelta += 1; break;
                    case `complexity`: upliftDelta += 3; sponsorDelta += 1; break;
                    case `everything`: sponsorDelta -= 6; upliftDelta -= 3; coachKey = `coach_r1_everything`; break;
                }

                // Descope discipline — trying to fix everything dilutes everything.
                if (d.descope === `named`) { sponsorDelta += 5; upliftDelta += 3; }
                else { sponsorDelta -= 4; coachKey = (d.primaryGap === `everything`) ? coachKey : `coach_r1_nodescope`; }

                summaryKey = (d.symptom === `evidence` && d.primaryGap === `collective` && d.descope === `named`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // BLEND the three elements to the diagnosis (Common Error 2: lopsided).
                const s = d.wSelf, c = d.wColl, x = d.wComp;
                const maxW = Math.max(s, c, x);
                const minW = Math.min(s, c, x);

                // A deliberate, balanced-but-tilted blend beats both an even split and a lopsided one.
                if (maxW >= 60) {
                    ds.lopsided = true;
                    upliftDelta += 3; transferDelta -= 4; sponsorDelta -= 6; coachKey = `coach_r2_lopsided`;
                } else if (maxW <= 40 && minW >= 28) {
                    // Near-even split ignores the diagnosis.
                    upliftDelta += 4; sponsorDelta -= 2; coachKey = `coach_r2_even`;
                } else {
                    // Balanced but deliberately tilted — a real blend.
                    upliftDelta += 8; transferDelta += 4; sponsorDelta += 4; coachKey = `coach_r2_balanced`;
                }

                // Reward weighting toward the diagnosed primary gap from R1.
                const gap = ds.primaryGap;
                if (gap === `collective` && c >= s && c >= x && c < 60) { transferDelta += 8; sponsorDelta += 8; upliftDelta += 4; coachKey = `coach_r2_togap`; }
                else if (gap === `selfaware` && s >= c && s >= x && s < 60) { upliftDelta += 6; sponsorDelta += 4; }
                else if (gap === `complexity` && x >= s && x >= c && x < 60) { upliftDelta += 6; sponsorDelta += 4; }
                else if (gap && gap !== `everything`) { sponsorDelta -= 5; coachKey = `coach_r2_misblend`; }

                // The merger silos need collective work no matter the primary gap.
                if (c <= 15) { sponsorDelta -= 6; transferDelta -= 5; coachKey = `coach_r2_nosilo`; }

                // Sequence the 9-month journey.
                switch (d.sequence) {
                    case `logical`: transferDelta += 6; upliftDelta += 3; sponsorDelta += 3; break;
                    case `frontload`: transferDelta -= 6; coachKey = `coach_r2_frontload`; break;
                    case `random`: transferDelta -= 3; sponsorDelta -= 2; break;
                }

                summaryKey = (!ds.lopsided && d.sequence === `logical` && c >= 20) ? `sum_r2_good` :
                             (ds.lopsided ? `sum_r2_lopsided` : `sum_r2_weak`);
            } else if (round === 3) {
                // ALLOCATE formats within £600k (Common Errors 3 & 4).
                const fa = d.faculty, ac = d.action, co = d.coaching, la = d.labs, pe = d.peer;
                const total = fa + ac + co + la + pe;
                ds.budgetUsed = Math.round(total);

                // Transfer-to-practice per pound: action-learning, coaching and labs transfer
                // best; faculty builds knowledge but transfers weakly; peer/digital sustains it.
                // Coefficients are per £100k of spend.
                const u = total > 0 ? 1 : 0;
                upliftDelta += (fa * 0.020 + ac * 0.030 + co * 0.034 + la * 0.026 + pe * 0.014);
                transferDelta += (fa * 0.008 + ac * 0.040 + co * 0.030 + la * 0.024 + pe * 0.022);

                // Faculty-heavy didactic default: cheap, scalable, engages — transfers nothing.
                if (fa >= 300) { transferDelta -= 10; sponsorDelta -= 6; coachKey = `coach_r3_didactic`; }

                // Budget blow-out chasing every high-transfer format for all 120.
                if (total > this.BUDGET) {
                    ds.overBudget = true;
                    const over = total - this.BUDGET;
                    disciplineDelta -= Math.min(45, 15 + over * 0.12);
                    sponsorDelta -= Math.min(20, 6 + over * 0.04);
                    coachKey = `coach_r3_blowout`;
                } else if (total < this.BUDGET - 120) {
                    // Coming in well under by defaulting to the cheapest formats = false economy.
                    disciplineDelta -= 12; transferDelta -= 6; sponsorDelta -= 4;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_underspend`;
                } else {
                    // Disciplined use of the full budget.
                    disciplineDelta += 14;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_balanced`;
                }

                // Scaling logic — reserve the deep formats where transfer matters most.
                switch (d.scale) {
                    case `targeted`: transferDelta += 8; sponsorDelta += 6; disciplineDelta += 6; if (!ds.overBudget && fa < 300) coachKey = `coach_r3_targeted`; break;
                    case `everyone`: if (!ds.overBudget) { sponsorDelta -= 2; } break;
                    case `cheapest`: transferDelta -= 6; upliftDelta -= 3; sponsorDelta -= 4; coachKey = `coach_r3_cheapest`; break;
                }

                upliftDelta *= u; transferDelta *= u;
                summaryKey = (!ds.overBudget && total >= this.BUDGET - 120 && ac >= 120 && fa < 300 && d.scale === `targeted`) ? `sum_r3_good` :
                             (ds.overBudget ? `sum_r3_blowout` : `sum_r3_weak`);
            } else if (round === 4) {
                // DEFEND the design & build in measurement (Common Error 5: happy-sheet).
                switch (d.pitch) {
                    case `outcome`: sponsorDelta += 12; transferDelta += 4; coachKey = `coach_r4_outcome`; break;
                    case `inspire`: sponsorDelta -= 6; ds.happySheet = true; coachKey = `coach_r4_inspire`; break;
                    case `defer`: sponsorDelta -= 4; transferDelta -= 6; coachKey = `coach_r4_defer`; break;
                }

                // Build measurement of capability uplift & transfer into the design (Kirkpatrick).
                switch (d.measure) {
                    case `behaviour`: sponsorDelta += 14; transferDelta += 10; upliftDelta += 4; if (d.pitch === `outcome`) coachKey = `coach_r4_measured`; break;
                    case `learning`: sponsorDelta += 2; upliftDelta += 3; transferDelta -= 2; coachKey = `coach_r4_learning`; break;
                    case `happysheet`: sponsorDelta -= 10; transferDelta -= 6; ds.happySheet = true; coachKey = `coach_r4_happysheet`; break;
                }

                // The sponsor pushes for "just keynotes for all 120."
                switch (d.pressure) {
                    case `hold`: sponsorDelta += 8; transferDelta += 4; break;
                    case `fold`: sponsorDelta -= 4; transferDelta -= 10; upliftDelta -= 4; ds.happySheet = true; coachKey = `coach_r4_fold`; break;
                    case `split`: sponsorDelta -= 2; transferDelta -= 8; coachKey = `coach_r4_split`; break;
                }

                if (d.conviction >= 60) { sponsorDelta += 5; }
                else if (d.conviction <= 25) { sponsorDelta -= 5; }

                summaryKey = (d.pitch === `outcome` && d.measure === `behaviour` && d.pressure === `hold`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas, clamped (KPIs 0–100). Budget discipline floats independently.
            ds.uplift = Math.max(0, Math.min(100, Math.round(ds.uplift + upliftDelta)));
            ds.transfer = Math.max(0, Math.min(100, Math.round(ds.transfer + transferDelta)));
            ds.sponsor = Math.max(0, Math.min(100, Math.round(ds.sponsor + sponsorDelta)));
            ds.discipline = Math.max(0, Math.min(100, Math.round(ds.discipline + disciplineDelta)));

            ds.upliftHistory.push(ds.uplift);
            ds.transferHistory.push(ds.transfer);
            ds.sponsorHistory.push(ds.sponsor);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                uplift: ds.uplift,
                upliftDelta: Math.round(upliftDelta),
                transfer: ds.transfer,
                transferDelta: Math.round(transferDelta),
                sponsor: ds.sponsor,
                sponsorDelta: Math.round(sponsorDelta),
                discipline: ds.discipline,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                happySheet: ds.happySheet,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(vk) {
            // Locale-aware GBP, value already in £k. English "£600k", Spanish "600k £".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = vk < 0 ? `-` : ``;
            const abs = Math.round(Math.abs(vk));
            if (lang === `es`) {
                return `${sign}${abs} k £`;
            }
            return `${sign}£${abs}k`;
        }

