            uiManager.bind(`transferDisplay`, `domainState.transfer`, (v) => Math.round(Number(v)));
            uiManager.bind(`sponsorDisplay`, `domainState.sponsor`, (v) => {
                const card = document.querySelector(`.tlsdesign-card-sponsor`);
                if (card) {
                    card.classList.toggle(`tlsdesign-sponsor-high`, Number(v) >= 65);
                    card.classList.toggle(`tlsdesign-sponsor-low`, Number(v) <= 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`disciplineDisplay`, `domainState.discipline`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.tlsdesign-budget-bar`);
                if (bar) bar.classList.toggle(`tlsdesign-budget-over`, Number(v) > self.BUDGET);
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
            });

            // Blend live total (must hit 100%).
            const blendIds = [`wSelfInput`, `wCollInput`, `wCompInput`];
            const blendReadout = document.getElementById(`blendReadout`);
            const recomputeBlend = function() {
                let total = 0;
                blendIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (blendReadout) blendReadout.textContent = total;
                const bar = blendReadout ? blendReadout.parentElement : null;
                if (bar) bar.style.color = (total !== 100) ? `#b23b3b` : ``;
            };
            blendIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeBlend);
            });
            recomputeBlend();

            // Budget live total (must hit £600k).
            const costIds = [`facultyInput`, `actionInput`, `coachingInput`, `labsInput`, `peerInput`];
            const costReadout = document.getElementById(`costReadout`);
            const recomputeCost = function() {
                let total = 0;
                costIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (costReadout) costReadout.textContent = total;
                const bar = costReadout ? costReadout.parentElement : null;
                if (bar) bar.style.color = (total > self.BUDGET) ? `#b23b3b` : (total < self.BUDGET - 120 ? `#b07a18` : ``);
            };
            costIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeCost);
            });
            recomputeCost();
        }

