        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const uplift = Math.round(ds.uplift);
            const transfer = Math.round(ds.transfer);
            const sponsor = Math.round(ds.sponsor);
            const discipline = Math.round(ds.discipline);

            // v1.1.0 — reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const transfers = transfer >= 60;
            const credible = uplift >= 55 && sponsor >= 60;
            const budgeted = discipline >= 55 && !ds.overBudget;
            const happySheetFail = ds.happySheet && transfer < 50;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_undefensible`;
            if (transfers && credible && budgeted && composite >= 75) tierKey = `grade_renewal`;
            else if (transfers && credible) tierKey = `grade_capability`;
            else if (happySheetFail) tierKey = `grade_happysheet`;
            else if (ds.overBudget) tierKey = `grade_overbudget`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (transfers && credible && budgeted) insights.push(window.mySimulation.t(`insight_renewal`));
            else if (happySheetFail) insights.push(window.mySimulation.t(`insight_happysheet`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (transfer < 50) insights.push(window.mySimulation.t(`insight_transfer_low`));
            else if (transfer >= 70) insights.push(window.mySimulation.t(`insight_transfer_strong`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (ds.lopsided) insights.push(window.mySimulation.t(`insight_lopsided`));
            if (!ds.diagnosed) insights.push(window.mySimulation.t(`insight_nodiagnosis`));
            if (ds.primaryGap === `collective` && sponsor >= 60) insights.push(window.mySimulation.t(`insight_silotargeted`));

            return {
                uplift: uplift,
                transfer: transfer,
                sponsor: sponsor,
                discipline: discipline,
                transfers: transfers,
                credible: credible,
                budgeted: budgeted,
                happySheet: happySheetFail,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

