            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="thm-cm">` +
  `<div class="thm-cm-head">` +
    `<div class="thm-cm-score"><div class="thm-cm-score-num">` + Math.round(s.composite) +
